{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "ON013100, a methoxy-substituted aromatic compound, achieved a quasi-steady-state brain/plasma concentration ratio of 0.92 in an orthotopic U87 glioma mouse model, demonstrating high brain penetration and supporting meaningful CNS access for the query's neutral methoxyaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pterostilbene, a methoxy-substituted polyphenol, reached 141.4 ng/g in rat brain after systemic administration, directly demonstrating blood-brain barrier permeation and supporting the query's CNS access potential.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A methoxyaryl iodinated ether showed initial brain uptake of 4.37% ID/g at 2 min post-injection in mice, providing direct in vivo evidence of BBB penetration for a structurally related neutral lipophilic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A dimethoxyaryl iodinated compound exhibited high initial brain uptake and rapid washout (brain2min/brain60min ratio 16.3), consistent with meaningful CNS access and supporting the query's favorable passive diffusion profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paeonol, a methoxyphenol, was detected in rat brain after administration, confirming its ability to cross the blood-brain barrier and supporting the query's predicted CNS penetration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple highly transferable in vivo measurements in methoxyaryl/neutral lipophilic analogues demonstrate meaningful BBB penetration, and the physicochemical prior is favorable with no strong efflux liability.",
  "evidence_gaps": [
    "No direct experimental brain or CSF exposure data for the exact query molecule.",
    "Efflux transporter interaction was not directly measured for the query, though the neutral non-basic character suggests low liability.",
    "Quantitative brain-to-plasma ratio for the query itself is not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

